WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET ECHO ON
SET FEEDBACK ON
SET HEADING ON
SET PAGESIZE 50
SET LINESIZE 160

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE produtos_carga PURGE';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -942 THEN
      RAISE;
    END IF;
END;
/

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE produtos PURGE';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -942 THEN
      RAISE;
    END IF;
END;
/

CREATE TABLE produtos (
  id_produto   NUMBER PRIMARY KEY,
  nome_produto VARCHAR2(100) NOT NULL,
  categoria    VARCHAR2(50) NOT NULL,
  preco        NUMBER(10, 2) NOT NULL,
  criado_em    TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
  CONSTRAINT ck_produtos_preco CHECK (preco >= 0)
);

CREATE TABLE produtos_carga (
  id_produto   NUMBER PRIMARY KEY,
  nome_produto VARCHAR2(100) NOT NULL,
  categoria    VARCHAR2(50) NOT NULL,
  preco        NUMBER(10, 2) NOT NULL,
  CONSTRAINT ck_produtos_carga_preco CHECK (preco >= 0)
);


COMMIT;

SELECT COUNT(*) AS total_produtos
FROM produtos;

SELECT COUNT(*) AS total_produtos_carga
FROM produtos_carga;

EXIT;

